DROP TABLE IF EXISTS `employee_reporting_lines`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `employee_reporting_lines` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `employee_assignment_id` bigint(20) unsigned NOT NULL,
  `supervisor_assignment_id` bigint(20) unsigned NOT NULL,
  `started_at` date NOT NULL,
  `ended_at` date DEFAULT NULL,
  `current_assignment_id` bigint(20) unsigned GENERATED ALWAYS AS (case when `ended_at` is null then `employee_assignment_id` else NULL end) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `reporting_start_unique` (`employee_assignment_id`,`started_at`),
  UNIQUE KEY `employee_current_supervisor_unique` (`current_assignment_id`),
  KEY `reporting_supervisor_index` (`supervisor_assignment_id`),
  CONSTRAINT `employee_reporting_lines_ibfk_1` FOREIGN KEY (`employee_assignment_id`) REFERENCES `employee_assignments` (`id`),
  CONSTRAINT `employee_reporting_lines_ibfk_2` FOREIGN KEY (`supervisor_assignment_id`) REFERENCES `employee_assignments` (`id`),
  CONSTRAINT `CONSTRAINT_1` CHECK (`employee_assignment_id` <> `supervisor_assignment_id`),
  CONSTRAINT `CONSTRAINT_2` CHECK (`ended_at` is null or `ended_at` >= `started_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
